@@ -269,6 +269,8 @@ export async function POST(req: Request) {
     const defaultModel = await getBaseModelByFileName(DEFAULT_BASE_MODEL);
     const imageGenerationCost =
       defaultModel?.tokenCost ?? IMAGE_GENERATION_COST;
+    const imageGenerationCost2k = defaultModel?.tokenCost2k;
+    const imageGenerationCost4k = defaultModel?.tokenCost4k;

     // Get the base URL from environment variable
     const baseUrl = process.env.NEXT_PUBLIC_APP_URL || GAZAI_HOME_PAGE;
@@ -293,7 +295,7 @@ Your task is to help users with canvas-related work: create panels, generate ima

 You have access to the following tools:
 - createPanel: Creates a panel on the canvas with the specified dimensions. Panels are optional containers for organizing content — they are NOT required for image generation.
-- generateImage: Generates an image and places it directly on the canvas. Does NOT require a panel. Returns a seed value for character consistency. CRITICAL: Pass the user's prompt in their own language — if they write in Chinese/Japanese/other, the prompt parameter must be in that language. Never translate the prompt to English.
+- generateImage: Generates an image and places it directly on the canvas. Does NOT require a panel. Returns a seed value for character consistency. Supports resolution selection (1K/2K/4K). CRITICAL: Pass the user's prompt in their own language — if they write in Chinese/Japanese/other, the prompt parameter must be in that language. Never translate the prompt to English.
 - createText: Adds text to the canvas or to a specific panel with language-specific formatting

 IMPORTANT: Scope Limitation and Polite Refusal
@@ -314,14 +316,18 @@ IMPORTANT: Scope Limitation and Polite Refusal
 - Always stay focused on your core mission of assisting with Gazai's canvas functionality and creative development

 IMPORTANT: Token Cost and User Consent for Image Generation
-- Each image generation using generateImage tool consumes ${imageGenerationCost} tokens
-- Before using the generateImage tool, you MUST:
-  1. Inform the user about the token cost (${imageGenerationCost} tokens per image)
-  2. Ask for explicit user consent before proceeding
-  3. Only proceed with image generation after receiving clear user approval
-- Example consent request: "I need to generate an image which will cost ${imageGenerationCost} tokens. Do you want me to proceed with the image generation?"
+- Image generation costs depend on the selected resolution:
+  * 1K (standard): ${imageGenerationCost} tokens per image
+${imageGenerationCost2k ? `  * 2K (high resolution): ${imageGenerationCost2k} tokens per image\n` : ''}${imageGenerationCost4k ? `  * 4K (ultra high resolution): ${imageGenerationCost4k} tokens per image\n` : ''}- Before using the generateImage tool, you MUST:
+  1. Inform the user about the available resolutions and their token costs
+  2. Ask which resolution they prefer (default to 1K if they don't specify)
+  3. Ask for explicit user consent before proceeding
+  4. Only proceed with image generation after receiving clear user approval
+- Example consent request: "I can generate the image at different resolutions: 1K (${imageGenerationCost} tokens)${imageGenerationCost2k ? `, 2K (${imageGenerationCost2k} tokens)` : ''}${imageGenerationCost4k ? `, 4K (${imageGenerationCost4k} tokens)` : ''}. Which resolution would you like?"
 - If the user does not give explicit consent, do not use the generateImage tool
 - Always be transparent about token costs and respect user decisions
+- If the user has previously chosen a resolution in the same conversation, remember their preference for subsequent generations
+- IMPORTANT: When the image contains text (e.g. posters, banners, titles, captions, signs, logos with text), strongly recommend 4K resolution to the user. Text rendered at 1K or 2K often appears blurry or illegible. Explain that 4K produces much clearer, sharper text in generated images.

 IMPORTANT: Object Limit Handling
 - Users have object limits based on their membership plan
