           const seed = (args.seed as number) || getRandomSeed();
           const aspectRatio = args.aspectRatio as string;

+          // Map resolution string from tool call to GeminiResolution enum
+          const resolutionStr = args.resolution as string | undefined;
+          const resolution = resolutionStr
+            ? (Object.values(GeminiResolution).find(
+                (v) => v === resolutionStr
+              ) as GeminiResolution | undefined)
+            : undefined;
+
+          // Derive width/height from aspectRatio + resolution instead of using
