+          const resolutionMultiplier =
+            resolution === GeminiResolution.RESOLUTION_4K
+              ? 2
+              : resolution === GeminiResolution.RESOLUTION_2K
+                ? Math.SQRT2
+                : 1;
+          const width = Math.round(baseWidth * resolutionMultiplier);
+          const height = Math.round(baseHeight * resolutionMultiplier);
+
           if (typeof prompt !== 'string') {
